topic:
Refactor this legacy invoice code one small step at a time. The assert tests at the bottom must keep passing after every step, and they must not be changed or removed; you may add tests.

```python
TAX = 0.08

def calc(items, c, d):
    t = 0
    for i in items:
        if i[2] == 'book':
            t = t + i[1] * i[3]
        elif i[2] == 'food':
            t = t + i[1] * i[3]
        else:
            t = t + i[1] * i[3] + i[1] * i[3] * TAX
    if c == 'SAVE10':
        if t > 50:
            t = t - t * 0.1
        else:
            t = t
    elif c == 'SAVE20':
        if t > 100:
            t = t - t * 0.2
    if d == 'express':
        t = t + 15
    elif d == 'standard':
        if t < 35:
            t = t + 5
    return round(t, 2)

assert calc([('pen', 2.5, 'office', 4)], None, 'standard') == 15.8
assert calc([('novel', 12.0, 'book', 2), ('apple', 0.5, 'food', 10)], 'SAVE10', 'express') == 44.0
assert calc([('novel', 30.0, 'book', 2)], 'SAVE10', 'pickup') == 54.0
assert calc([('lamp', 60.0, 'home', 2)], 'SAVE20', 'standard') == 103.68
assert calc([], None, 'standard') == 5
print("All tests passed.")
```
